var line = new LabLine("L1");
var history = new List<LabRegistrationEvent>();
line.Changed += e => { history.Add(e); Console.WriteLine($"{e.LineId} {e.SipStatus} {e.State}"); };
line.Register(403); // L1 403 Failed
line.Register(200); // L1 200 Registered
Console.WriteLine(history.Count); // 2
Console.WriteLine(line.State); // Registered

var a = new LabLine("L-A");
var b = new LabLine("L-B");
var states = new Dictionary<string, string>();
void Apply(LabRegistrationEvent e) => states[e.LineId] = e.State;
a.Changed += Apply;
b.Changed += Apply;
a.Register(200);
b.Register(403);
bool CanUse(string id) => states.TryGetValue(id, out var state) && state == "Registered";
Console.WriteLine(CanUse("L-A")); // True
Console.WriteLine(CanUse("L-B")); // False
